  "status.ai": "AI",
  "status.voice": "ശബ്ദം",
  "status.email": "ഇമെയിൽ",
  "footer.built": "Build What Moves India ഹാക്കാത്തോണിനായി നിർമ്മിച്ചത്. ഒരു സർക്കാർ സ്ഥാപനവുമായോ അഫിലിയേറ്റ് ചെയ്തിട്ടുള്ളതോ അവ അംഗീകരിച്ചതോ ബന്ധപ്പെട്ടതോ അല്ല. എല്ലാ റഫറൻസ് നമ്പറുകളും മാതൃകാപരമാണ്.",
  "start.h1": "എന്ത് സംഭവിച്ചു എന്ന് ഞങ്ങളോട് പറയൂ.",
  "start.sub": "നിങ്ങളുടെ സ്വന്തം വാക്കുകളിൽ, വിശ്വസ്തനായ ഒരാളോട് വിശദീകരിക്കുന്നതുപോലെ പറയുക. പരിശോധിക്കുന്നതിനായി ഞങ്ങൾ നിങ്ങൾക്ക് ഘടനാപരമായ ഒരു ഡ്രാഫ്റ്റ് നിർദ്ദേശിക്കും.",
  "start.mic": "സംസാരിക്കാൻ അമർത്തിപ്പിടിക്കുക",
  "start.micStop": "കേൾക്കുന്നുണ്ട് — സംസാരിച്ചു കഴിഞ്ഞാൽ വിടുക",
  "start.micHint": "സംസാരിക്കുന്ന ഭാഷ:",
  "start.voiceDisclosure": "വോയ്‌സ് നിങ്ങളുടെ മൈക്രോഫോൺ ഉപയോഗിക്കുന്നു. ബ്രൗസർ സ്പീച്ച് റെക്കോഗ്നിഷൻ നിങ്ങളുടെ ബ്രൗസർ വെണ്ടറുടെ സ്പീച്ച് സർവീസ് വഴി പ്രോസസ്സ് ചെയ്‌തേക്കാം; റെക്കോർഡ് ചെയ്ത ഓഡിയോ മോഡ് റെക്കോർഡിംഗ് Kavach-ന്റെ കോൺഫിഗർ ചെയ്ത ട്രാൻസ്ക്രിപ്ഷൻ പ്രൊവൈഡർക്ക് അയയ്ക്കുന്നു. ഓഡിയോ ബൈറ്റുകൾ നിങ്ങളുടെ കേസ് ഫയലിലേക്ക് ചേർക്കില്ല, എന്നാൽ ഓരോ സർവീസിന്റെയും ഡാറ്റാ കൈകാര്യം ചെയ്യൽ ബാധകമായേക്കാം. വോയ്‌സ് പ്രോസസ്സിംഗ് ഒഴിവാക്കാൻ പകരം ടൈപ്പ് ചെയ്യുക.",
  "start.voiceConsent": "ഈ പ്രസ്താവനയ്ക്കായി മൈക്രോഫോൺ ആക്‌സസും വോയ്‌സ് ട്രാൻസ്ക്രിപ്ഷനും ഞാൻ മനസ്സിലാക്കുകയും സമ്മതം നൽകുകയും ചെയ്യുന്നു.",
  "start.or": "അല്ലെങ്കിൽ ടൈപ്പ് ചെയ്യുക",
  "start.placeholder": "ഉദാഹരണത്തിന്: ഇന്നലെ വൈകുന്നേരം ബാങ്കിൽ നിന്നാണെന്നു പറഞ്ഞ് ഒരാൾ വിളിച്ചു, എന്റെ കാർഡ് ബ്ലോക്ക് ചെയ്തുവെന്നു പറഞ്ഞു, OTP ചോദിച്ചു, മൂന്ന് ഇടപാടുകളിലായി എൺപതിനായിരം രൂപ നഷ്ടപ്പെട്ടു.",
  "start.examples": "എങ്ങനെ തുടങ്ങണമെന്ന് ഉറപ്പില്ലേ? ഇതിലൊന്ന് ശ്രമിച്ചു നോക്കൂ",
  "start.ex1": "ബാങ്ക് ഉദ്യോഗസ്ഥൻ ചമഞ്ഞ് ആരെങ്കിലും വിളിച്ച് OTP എടുത്തു",
  "start.ex2": "ഫോൺ വാങ്ങാൻ ഞാൻ ഒരു വെബ്‌സൈറ്റിൽ പണം നൽകി, എന്നാൽ അത് എത്തിയില്ല",
  "start.ex3": "പോലീസാണെന്ന് അവകാശപ്പെട്ട് വീഡിയോ കോൾ ചെയ്ത് എന്നെ ഡിജിറ്റൽ അറസ്റ്റ് ചെയ്തതായി പറഞ്ഞു",
  "start.ex4": "എന്റെ ഫോട്ടോകൾ ഉപയോഗിച്ച് ആരെങ്കിലും വ്യാജ ഇൻസ്റ്റാഗ്രാം അക്കൗണ്ട് ഉണ്ടാക്കി",
  "start.ex5": "വാട്‌സാപ്പിലെ ഒരു നിക്ഷേപ ഗ്രൂപ്പ് എന്റെ പണം തട്ടിയെടുത്ത് മുങ്ങി",
  "start.submit": "തുടരുക",
  "start.analysing": "നിങ്ങൾ എഴുതിയത് വായിക്കുന്നു",
  "start.analysing2": "ഔദ്യോഗിക വിഭാഗങ്ങളുമായി പൊരുത്തപ്പെടുത്തുന്നു",
  "start.analysing3": "നിങ്ങളുടെ ഉത്തരങ്ങൾക്ക് അനുയോജ്യമായ നടപടികൾ തയ്യാറാക്കുന്നു",
  "start.privacy": "നിങ്ങളുടെ Aadhaar നമ്പർ, PAN, കാർഡ് PIN, പാസ്‌വേഡ് അല്ലെങ്കിൽ ഏതെങ്കിലും OTP എന്നിവ ടൈപ്പ് ചെയ്യരുത്. ഞങ്ങൾക്ക് അവ ഒരിക്കലും ആവശ്യമില്ല.",
  "start.tooShort": "സ്വന്തം വാക്കുകൾ അല്പം കൂടി ചേർക്കുക — ഒരു വാടകം കൂടി ചേർത്താൽ പോലും അത് കൃത്യമായി തരംതിരിക്കാൻ ഞങ്ങളെ സഹായിക്കും.",
  "start.error": "അത് സമർപ്പിക്കാൻ കഴിഞ്ഞില്ല. നിങ്ങളുടെ വാചകം സുരക്ഷിതമാണ്. വീണ്ടും ശ്രമിക്കുക.",
  "start.saveError": "ഈ ബ്രൗസറിന് കേസ് ഫയൽ സേവ് ചെയ്യാനായില്ല. ഈ പേജ് തുറന്നു വെക്കുക, ഡിവൈസ് സ്റ്റോറേജ് ഫ്രീ ചെയ്യുക അല്ലെങ്കിൽ ബ്രൗസർ പ്രൈവസി ക്രമീകരണങ്ങൾ മാറ്റുക, തുടർന്ന് വീണ്ടും കേസ് നിർമ്മിക്കാൻ ശ്രമിക്കുക.",
  "start.voiceUnsupported": "ഈ ബ്രൗസറിന് റെക്കോർഡ് ചെയ്യാൻ കഴിയില്ല. ദയവായി പകരം ടൈപ്പ് ചെയ്യുക.",
  "start.resume": "നിങ്ങളുടെ ഒരു കേസ് പുരോഗമിച്ചുകൊണ്ടിരിക്കുന്നു",
