  "triage.found": "നിങ്ങളുടെ വിവരണത്തിൽ നിന്ന് ഞങ്ങൾ കണ്ടെത്തിയ വിവരങ്ങൾ",
  "triage.nothingFound": "നിങ്ങളുടെ വിവരണത്തിൽ ഞങ്ങൾ സംഖ്യകളൊന്നും കണ്ടെത്തിയില്ല. അടുത്ത ഘട്ടത്തിൽ നിങ്ങൾക്ക് അവ ചേർക്കാം.",
