  "build.skip": "ഇത് പിന്നീട് ചെയ്യാം",
  "build.next": "അടുത്തത്",
  "build.back": "പിന്നോട്ട്",
  "build.finish": "പൂർത്തിയാക്കുക",
  "build.optional": "നിർബന്ധമില്ലാത്തത്",
  "build.required": "ആവശ്യമാണ്",
  "build.evidence.t": "തട്ടിപ്പുകാരൻ നിങ്ങൾക്ക് അയച്ച എന്തും ഇവിടെ പേസ്റ്റ് ചെയ്യുക",
  "build.evidence.b": "SMS, വാട്സാപ്പ് സന്ദേശം, ഇമെയിൽ, ബാങ്ക് അലേർട്ട്. ഒറിജിനൽ ടെക്സ്റ്റ് പേസ്റ്റ് ചെയ്യുക — ഞങ്ങൾ അതിൽ നിന്ന് പ്രധാനപ്പെട്ട നമ്പറുകൾ എടുത്തു കൊള്ളാം, നിങ്ങൾ അവ ടൈപ്പ് ചെയ്യേണ്ടി വരില്ല.",
  "build.evidence.ph": "സന്ദേശം ഇവിടെ പേസ്റ്റ് ചെയ്യുക. ഒന്നിലധികം സന്ദേശങ്ങൾ ആകാം.",
  "build.evidence.extract": "വിശദാംശങ്ങൾ പുറത്തെടുക്കുക",
  "build.evidence.extracting": "വായിക്കുന്നു",
  "build.evidence.found": "കണ്ടെത്തി",
  "build.evidence.none": "അതിൽ തിരിച്ചറിയാൻ തക്കവണ്ണം ഒന്നും ഇല്ല. പകരം നിങ്ങൾക്ക് താഴെയുള്ള വിശദാംശങ്ങൾ ടൈപ്പ് ചെയ്യാം.",
  "build.evidence.files": "സ്ക്രീൻഷോട്ടുകളും സ്റ്റേറ്റ്‌മെന്റുകളും",
  "build.evidence.filesHint": "ചിത്രങ്ങളും PDF ഫയലുകളും. ഇവ നിങ്ങളുടെ ഫോണിൽ തന്നെ സൂക്ഷിക്കപ്പെടും — സ്റ്റേഷനിൽ കൊണ്ടുപോകേണ്ടത് ഏതൊക്കെയാണെന്ന് അറിയാൻ ഞങ്ങൾ അവ കേസ് പായ്ക്കിൽ ഉൾപ്പെടുത്താം.",
