  "g.no": "ഇല്ല",
  "g.notSet": "നൽകിയിട്ടില്ല",
  "g.today": "ഇന്ന്",
  "g.tomorrow": "നാളെ",
  "g.days": "ദിവസങ്ങൾ",
  "g.hours": "മണിക്കൂറുകൾ",
  "g.minutes": "മിനിറ്റുകൾ",
  "g.aiNote": "നിങ്ങൾ ഞങ്ങളോട് പറഞ്ഞ വിവരങ്ങൾ വെച്ച് AI എഴുതിയത്. അയക്കുന്നതിന് മുൻപ് ഇത് വായിക്കുക.",
  "g.offline": "നിങ്ങൾ ഓഫ്‌ലൈനിലാണ്. നിങ്ങൾ നൽകിയതെല്ലാം സേവ് ചെയ്തിട്ടുണ്ട്.",
