  "intake.evEmail": "Email",
  "intake.evLink": "വെബ്‌സൈറ്റ് അല്ലെങ്കിൽ ആപ്പ് ലിങ്ക്",
  "intake.evNone": "ഒന്നുമില്ല ഇതുവരെ",
  "intake.evidenceCta": "കയ്യിലുള്ളത് സേവ് ചെയ്യുക",
  "intake.routingQ": "കേസ് എവിടേക്കാണ് അയക്കേണ്ടത്?",
  "intake.routingSub": "നിലവിൽ സംസ്ഥാനം മതിയാകും. ശരിയായ പോലീസിനെയും നടപടിക്രമങ്ങളെയും തയ്യാറാക്കാൻ ജില്ലാ സഹായകരമാകും. ഇത് നിങ്ങളുടെ സ്ഥാനം പങ്കിടുന്നില്ല.",
  "intake.state": "സംസ്ഥാനം അല്ലെങ്കിൽ കേന്ദ്രഭരണ പ്രദേശം",
  "intake.district": "ജില്ല അല്ലെങ്കിൽ നഗരം",
  "intake.routingCta": "ഈ സ്ഥാനം ഉപയോഗിക്കുക",
  "intake.routingSkip": "ഞാൻ പിന്നീട് ചേർക്കാം",
  "detail.intro": "ബുദ്ധിമുട്ടേറിയ ഭാഗം കഴിഞ്ഞു. ഇനി കുറച്ച് ചെറിയ ചോദ്യങ്ങൾ, നിങ്ങൾ അയക്കുമ്പോൾ ഓരോ ഉത്തരവും ഈ ചാറ്റിന് അടുത്തുള്ള കേസ് ഫയലിൽ ചേരും.",
  "detail.introOptional": "ഇതാണ് കൗണ്ടറിൽ പൂരിപ്പിക്കാനുള്ള വിടവുകളില്ലാതെ നിങ്ങളുടെ കത്തുകൾ പൂർത്തിയായി ലഭിക്കുന്നത് ഉറപ്പാക്കുന്നത്. ഇതിൽ ഏത് ചോദ്യവും ഒഴിവാക്കാം — നിങ്ങൾക്ക് അവ പിന്നീട് ചേർക്കാം.",
  "detail.counter": "ചോദ്യം",
