  "detail.knownAlready": "നിങ്ങൾ പറഞ്ഞതിൽ നിന്ന് ഇതിനകം ഉത്തരം നൽകി",
  "detail.skip": "ഇത് ഒഴിവാക്കുക",
  "detail.skipAll": "ബാക്കിയുള്ളവ ഒഴിവാക്കുക",
  "detail.next": "സേവ് ചെയ്ത് തുടരുക",
  "detail.skipped": "(ഒഴിവാക്കി)",
  "detail.typeOrSay": "നിങ്ങളുടെ ഉത്തരം ടൈപ്പ് ചെയ്യുക, അല്ലെങ്കിൽ മൈക്രോഫോണിൽ ടാപ്പ് ചെയ്ത് പറയുക.",
  "detail.done": "എനിക്ക് ചോദിക്കാൻ കഴിയ는തെല്ലാം ചോദിച്ചു കഴിഞ്ഞു. നിങ്ങളുടെ രേഖകളിൽ ഇവയെല്ലാം പൂരിപ്പിച്ചതായിരിക്കും വരുന്നത്.",
  "detail.groupYou": "നിങ്ങൾ",
