  "ev.next": "അടുത്തത്:",
  "ev.overviewDisclaimer": "ചെക്ക്‌ലിസ്റ്റ് പൂർത്തിയായി എന്നത് തെളിവുകൾ ആധികാരികമാണെന്നോ, പര്യാപ്തമാണെന്നോ അല്ലെങ്കിൽ Kavach-ൽ സൂക്ഷിച്ചിട്ടുണ്ടെന്നോ ഉള്ള തെളിവല്ല.",
