  "ev.mostAddressed": "കൂടുതൽ ഇനങ്ങളും പരിഹരിച്ചു",
  "ev.inProgress": "ചെക്ക്‌ലിസ്റ്റ് പുരോഗമിക്കുന്നു",
  "ev.justStarted": "ചെക്ക്‌ലിസ്റ്റ് ഇപ്പോൾ ആരംഭിച്ചു",
  "ev.preserveNote": "സുരക്ഷിതമാണെങ്കിൽ, തുടർന്ന് ബന്ധപ്പെടുകയോ അടിയന്തര സഹായം വൈകിക്കുകയോ ചെയ്യാതെ യഥാർത്ഥ റെക്കോർഡുകൾ സൂക്ഷിക്കുക. ഈ സ്കോർ നിങ്ങളുടെ ചെക്ക്‌ലിസ്റ്റ് ട്രാക്ക് ചെയ്യുന്നു; ഇത് നിയമപരമായ പര്യാപ്തതയോ ആധികാരികതയോ തീരുമാനിക്കുന്നില്ല.",
  "ev.recommendedNext": "ശുപാർശ ചെയ്യുന്ന അടുത്തത്",
  "ev.storageNote": "ഇവിടെ അറ്റാച്ചുചെയ്തിരിക്കുന്ന ഫയലുകൾ ഈ ബ്രൗസറിന്റെ IndexedDB-യിൽ യഥാർത്ഥ ബൈറ്റുകളായി സംഭരിക്കുകയും SHA-256 ഉപയോഗിച്ച് ഫിംഗർപ്രിന്റ് ചെയ്യുകയും ചെയ്യുന്നു. അവ Kavach-ന്റെ സെർവറിലേക്കോ AI മോഡലിലേക്കോ അയയ്‌ക്കില്ല. സൈറ്റ് ഡാറ്റ ക്ലിയർ ചെയ്യുന്നത് അവയെ ഇല്ലാതാക്കുന്നു; ഒറിജിനലുകളും സൂക്ഷിക്കുക.",
  "ev.manifestTitle": "പ്രിന്റ് ചെയ്യാവുന്ന തെളിവ് മാനിഫെസ്റ്റ്",
  "ev.manifestBody": "നിങ്ങളുടെ കൈവശമുള്ളത് എന്തൊക്കെയാണ്, എന്തൊക്കെയാണ് നഷ്ടപ്പെട്ടത്, നിങ്ങളുടെ സമയപരിധി, ലഭ്യമായ ഫിംഗർപ്രിന്റുകൾ എന്നിവയുടെ PDF ചെക്ക്‌ലിസ്റ്റ് ജനറേറ്റ് ചെയ്യുക. PDF-ൽ തെളിവ് ഫയലുകൾ ഉൾപ്പെടുത്തിയിട്ടില്ല, അതൊരു ഔദ്യോഗിക പരാതിയുമല്ല.",
  "ev.generateSummary": "തെളിവ് സംഗ്രഹം ജനറേറ്റ് ചെയ്യുക",
  "ev.checklistH2": "തെളിവുകളുടെ ചെക്ക്‌ലിസ്റ്റ്",
  "ev.checklistSub": "ഓരോ ഇനവും എന്തിനാണ് പ്രധാനമെന്ന് കാണിക്കുന്നു. ചേർത്തു, നഷ്ടപ്പെട്ടു അല്ലെങ്കിൽ ബാധകമല്ല എന്ന് അടയാളപ്പെടുത്തുക. PNG, JPG അല്ലെങ്കിൽ PDF അറ്റാച്ചുചെയ്യുക (പരമാവധി 10 MB).",
  "ev.cat.transaction": "ഇടപാട് തെളിവ്",
