  "ev.cat.complaint": "പരാതിയും തുടർനടടപടികളും സംബന്ധിച്ച തെളിവ്",
  "ev.status.added": "കയ്യിലുണ്ടെന്ന് അടയാളപ്പെടുത്തി",
