  "ev.recordOnly": "റെക്കോർഡ് മാത്രം — ഫയൽ ബൈറ്റുകൾ ലഭ്യമല്ല",
  "ev.downloadCopy": "ലോക്കൽ കോപ്പി ഡൗൺलोड് ചെയ്യുക",
  "ev.remove": "നീക്കം ചെയ്യുക",
  "ev.heldElsewhere": "മറ്റിടങ്ങളിൽ സൂക്ഷിച്ചിരിക്കുന്നതായി അടയാളപ്പെടുത്തിയിരിക്കുന്നു; Kavach-ൽ ഈ ഇനത്തിനായി ലോക്കൽ ഫയലുകളില്ല.",
