  "ev.attachFile": "ഫയൽ അറ്റാച്ചുചെയ്യുക",
  "ev.replaceFile": "ഫയൽ മാറ്റിസ്ഥാപിക്കുക",
  "ev.markHeld": "മറ്റിടങ്ങളിൽ സൂക്ഷിച്ചതായി അടയാളപ്പെടുത്തുക",
  "ev.markMissing": "കാണാതായതായി അടയാളപ്പെടുത്തുക",
  "ev.change": "മാറ്റുക",
  "ev.storing": "സൂക്ഷിക്കുകയും ഫിംഗർപ്രിന്റ് ചെയ്യുകയും ചെയ്യുന്നു...",
  "ev.block.child": "കുട്ടികളുടെ സുരക്ഷയുമായി ബന്ധപ്പെട്ട ഈ കേസിൽ ലോക്കൽ അറ്റാച്ച്മെന്റ് പ്രവർത്തനരഹിതമാക്കിയിരിക്കുന്നു. 18 വയസ്സിന് താഴെയുള്ള ആരെയും ഉൾപ്പെടുന്ന ലൈംഗിക വസ്തുക്കൾ അപ്‌ലോഡ് ചെയ്യുകയോ ഫൊർവേർഡ് ചെയ്യുകയോ ഡൗൺലോഡ് ചെയ്യുകയോ മറ്റൊരു പകർപ്പ് ഉണ്ടാക്കുകയോ ചെയ്യരുത്. മെറ്റീരിയൽ വീണ്ടും തുറക്കാതെ ഉറവിട ഉപകരണം, URL അല്ലെങ്കിൽ അക്കൗണ്ട് വിശദാംശങ്ങൾ സംരക്ഷിക്കുക, കൂടാതെ 1098, 112 അല്ലെങ്കിൽ പരിശീലനം ലഭിച്ച ഒരു സേഫ്ഗാർഡിംഗ് പ്രൊഫഷണലിനെ ബന്ധപ്പെടുക.",
  "ev.block.intimate": "ഈ സ്വകാര്യ ഉള്ളടക്ക കേസിൽ ലോക്കൽ അറ്റാച്ച്മെന്റ് പ്രവർത്തനരഹിതമാക്കിയിരിക്കുന്നു, അതുവഴി Kavach മറ്റൊരു പകർപ്പ് സൃഷ്ടിക്കുന്നില്ല. മെറ്റീരിയൽ ഫൊർവേർഡ് ചെയ്യാതെ ഉറവിട ഉപകരണം, URL അല്ലെങ്കിൽ അക്കൗണ്ട് വിശദാംശങ്ങൾ സംരക്ഷിക്കുക. നിങ്ങൾക്ക് ഇപ്പോഴും ഒരു ഇനം മറ്റിടങ്ങളിൽ സൂക്ഷിച്ചതായി അടയാളപ്പെടുത്താം.",
  "ev.err.type": "PNG, JPG, PDF ഫയലുകൾ മാത്രമേ സ്വീകരിക്കൂ.",
  "ev.err.size": "ഫയൽ വളരെ വലുതാണ് — പരമാവധി 10 MB.",
  "ev.err.empty": "ഫയൽ കാലിയാണ്.",
  "ev.err.link": "കേസ് റെക്കോർഡ് സേവ് ചെയ്യാൻ കഴിയാത്തതിനാൽ ഫയൽ ബൈറ്റുകൾ ലിങ്ക് ചെയ്തിട്ടില്ല. മുൻത്തെ അറ്റാച്ച്മെന്റ് മാറ്റമില്ലാതെ തുടരുന്നു.",
  "ev.err.orphanNew": "കേസ് റെക്കോർഡ് സേവ് ചെയ്യാനും പുതിയതും ട്രാക്ക് ചെയ്യാത്തതുമായ തെളിവ് ബൈറ്റുകൾ നീക്കം ചെയ്യാനും ബ്രൗസറിന് കഴിഞ്ഞില്ല. മുൻത്തെ അറ്റാച്ച്മെന്റ് മാറ്റമില്ലാതെ തുടരുന്നു. ഉപേക്ഷിക്കപ്പെട്ട പകർപ്പ് നീക്കം ചെയ്യാൻ Kavach സൈറ്റ് ഡാറ്റ ക്ലിയർ ചെയ്യുക.",
  "ev.err.orphanOld": "പകരം വെച്ചത് സേവ് ചെയ്യുകയും അതിന്റെ ഫിംഗർപ്രിന്റ് പൊരുത്തപ്പെടുകയും ചെയ്യുന്നു, എന്നാൽ പഴയ ഉപേക്ഷിക്കപ്പെട്ട പകർപ്പ് നീക്കം ചെയ്യാൻ ബ്രൗസറിന് കഴിഞ്ഞില്ല. നിങ്ങൾക്ക് ആവശ്യമുള്ള ഒറിജിനലുകൾ സൂക്ഷിച്ചതിന് ശേഷം Kavach സൈറ്റ് ഡാറ്റ ക്ലിയർ ചെയ്യുക.",
  "ev.err.removeKept": "കേസ് റെക്കോർഡ് സേവ് ചെയ്യാൻ കഴിയാത്തതിനാൽ അറ്റാച്ച്മെന്റ് സൂക്ഷിച്ചിരിക്കുന്നു.",
  "ev.err.removeBytes": "അറ്റാച്ച്മെന്റ് റെക്കോർഡ് നീക്കം ചെയ്തു, എന്നാൽ ഉപേക്ഷിക്കപ്പെട്ട ലോക്കൽ ബൈറ്റുകൾ ഡിലീറ്റ് ചെയ്തത് ബ്രൗസറിന് സ്ഥിരീകരിക്കാൻ കഴിഞ്ഞില്ല. അവ നീക്കം ചെയ്യാൻ Kavach സൈറ്റ് ഡാറ്റ ക്ലിയർ ചെയ്യുക.",
  "ev.err.recordOnly": "ഫയൽ റെക്കോർഡ് മാത്രമേ ലഭ്യമാകൂ. അതിന്റെ ബൈറ്റുകൾ ഇവിടെ സൂക്ഷിക്കാൻ ഒറിജിനൽ ഫയൽ വീണ്ടും അറ്റാച്ചുചെയ്യുക.",
  "ev.err.gone": "ഫയൽ ഇനി ഈ ബ്രൗസറിലില്ല. സൈറ്റ് ഡാറ്റയ്ക്കൊപ്പം ഇത് നീക്കം ചെയ്തിട്ടുണ്ടാകാം.",
  "ev.err.store": "ഈ ബ്രൗസറിൽ ഫയൽ സൂക്ഷിക്കാൻ കഴിഞ്ഞില്ല.",
  "ev.err.open": "ലോക്കൽ ഫയൽ തുറക്കാൻ കഴിഞ്ഞില്ല.",
  "ev.err.removeLocal": "ലോക്കൽ ഫയൽ നീക്കം ചെയ്യാൻ കഴിഞ്ഞില്ല.",
