  "ev.tpl.txn_screenshot.why": "പ്രദർശിപ്പിച്ച തുക, സമയം, ഇടപാട് റഫറൻസ് എന്നിവ രേഖപ്പെടുത്താൻ സഹായിക്കുന്നു; അടിസ്ഥാന ബാങ്ക് റെക്കോർഡും സൂക്ഷിക്കുക.",
