  "ev.tpl.bank_statement.why": "അക്കൗണ്ട് സ്റ്റേറ്റ്‌മെന്റിൽ ഡെബിറ്റ് എങ്ങനെയാണ് കാണിക്കുന്നത് എന്ന് രേഖപ്പെടുത്തുകയും ബാങ്ക് തർക്കത്തെ പിന്തുണയ്ക്കുകയും ചെയ്യാം.",
