  "ev.tpl.sms_notification.why": "RBI-യുടെ സോപാധിക ബാധ്യത വിശകലനത്തിൽ പ്രധാനാർഹമായേക്കാവുന്ന, ബാങ്കിന്റെ സന്ദേശം നിങ്ങൾക്ക് എപ്പോഴാണ് ലഭിച്ചതെന്ന് സ്ഥാപിക്കാൻ സഹായിക്കുന്നു.",
