  "ev.tpl.chat_screenshot.why": "പ്രദർശിപ്പിച്ച വാഗ്ദാനങ്ങൾ, ആൾമാറാട്ടം അല്ലെങ്കിൽ നിർദ്ദേശങ്ങൾ സംരക്ഷിക്കുന്നു; അക്കൗണ്ട് നിയന്ത്രിച്ചത് ആരാണെന്ന് ഒരു സ്ക്രീൻഷോട്ട് മാത്രം തെളിയിക്കുന്നില്ല.",
