  "ev.tpl.email_correspondence.why": "സന്ദേശ ഉള്ളടക്കവും, ലഭ്യമാകുന്നിടത്ത്, അന്വേഷണ ഉദ്യോഗസ്ഥന് പരിശോധിക്കാൻ കഴിയുന്ന സാങ്കേതിക ഹെഡറുകളും സംരക്ഷിക്കുന്നു.",
