  "ev.tpl.website_url.title": "വെബ്സൈറ്റ് / ആപ്പ് URL",
  "ev.tpl.website_url.description": "നിങ്ങൾ സന്ദർശിച്ച വ്യാജ വെബ്സൈറ്റിലേക്കോ ആപ്പിലേക്കോ ഉള്ള ലിങ്ക്.",
  "ev.tpl.website_url.why": "ഒരു റിപ്പോർട്ടിനായി കൃത്യമായ സ്ഥാനം സംരക്ഷിക്കുന്നു. എന്തെങ്കിലും നിയന്ത്രണമോ നീക്കം ചെയ്യലോ ഉചിതമാണോ എന്ന് ഒരു പ്ലാറ്റ്‌ഫോമോ അംഗീകൃത ഏജൻസിയോ തീരുമാനിക്കുന്നു.",
  "ev.tpl.bank_ack.title": "ബാങ്ക് പരാതി സ്വീകടിച്ചതിന്റെ രീതി",
