  "ev.tpl.bank_ack.why": "നിങ്ങൾ എപ്പോഴാണ് ബാങ്കിനെ അറിയിച്ചതെന്നും എങ്ങനെയാണെന്നും തെളിയിക്കുന്നു; ബാധ്യതയ്ക്കും പിന്നീട് പരാതി ഉയർത്തുന്നതിനും സമയം പ്രസക്തമാണ്.",
  "ev.tpl.ncrp_ack.title": "NCRP പരാതി സ്വീകടിച്ചതിന്റെ രീതി",
