  "ev.tpl.fir_ack.why": "NCRP പോർട്ടൽ പരാതിയിൽ നിന്ന് വ്യത്യസ്തമായി പോലീസ് നടപടി രേഖപ്പെടുത്തുകയും പിന്നീട് പോലീസ്, ബാങ്ക് അല്ലെങ്കിൽ കോടതി തുടർനടപടികളെ പിന്തുണയ്ക്കുകയും ചെയ്തേക്കാം.",
